    "code": "    @Override\n    @Transactional\n    public Application saveApplication(Long applicationId, PharmacyBrandNameRenewalRequestDto requestDto,\n                                       @Nullable Application existingApplication) throws BaseException {\n        Application savedApplication = renewHandler.saveApplication(applicationId, requestDto, existingApplication,\n                (req, app) -> {\n                    app.setLicenseIds(req.getLicenseIds());\n\n                    PharmacyBrandNameRequestDto pharmacyBrandName = req.getPharmacyBrandName();\n                    boolean hasDetail = pharmacyBrandName != null;\n                    if (hasDetail && pharmacyBrandName.getPharmacyProfileId() != null) {\n                        ExternalProfileResponseDto profile = Optional.ofNullable(\n                                        profileAdapter.retrieveProfile(pharmacyBrandName.getPharmacyProfileId()))\n                                .map(ApiResponse::getData)\n                                .orElse(null);\n                        if (profile != null) {\n                            app.setApplicationNameEn(profile.getCompanyNameEn());\n                            app.setApplicationNameKh(profile.getCompanyNameKh());\n                        }\n                    }\n                    if (app.getId() == null) {\n                        prefillPartiesFromLastApprovedLicense(req, app, !hasDetail);\n                    }\n                });\n\n        if (requestDto.getPharmacyBrandName() != null) {\n            savePharmacyBrandNameDetail(savedApplication, requestDto.getPharmacyBrandName());\n        } else {\n            prefillFromLastApprovedLicense(requestDto, savedApplication);\n        }\n        return savedApplication;\n    }"
