  "rCommonsubmitApplication": {
    "repo": "MOH-Application",
    "rev": "8f1db657315e",
    "path": "src/main/java/kh/gov/esb/application/modules/application/service/ApplicationServiceImpl.java",
    "line": 339,
    "code": "    @Transactional\n    @Override\n    public SubmitApplicationResult submitApplication(Long applicationId, boolean forcePaymentFirst, Long facilityApplicationId, Long relationApplicationId, String trackingNo) throws BaseException {\n        Application application = getApplication(applicationId, authenticationFacade.getPublicUserId())\n                .orElseThrow(() -> new NotFoundException(\"application.not.found\"));\n\n        // Only a first submit is gated: returned or awaiting-payment applications are already in progress.\n        if (application.getStatus() == ApplicationStatus.DRAFT) {\n            serviceAvailabilityGate.assertOpen(application);\n        }\n\n        application.assignTrackingNo(resolveTrackingNo(application, trackingNo));\n\n        if (facilityApplicationId != null) {\n            application.setFacilityApplicationId(facilityApplicationId);\n        }\n\n        ApplicationStrategy strategy = applicationStrategyFactory.getStrategy(application.getServiceCode());\n\n        strategy.validateSubmitApplication(application);\n        // Configurable eligibility/window/prerequisite/reconciliation gate for RENEW/TRANSFER/UPDATE\n        // service codes — a no-op (defaults to pass) for services with no operation_rule_configs rows.\n        operationGate.assertSubmittable(application);\n        // service_relation_rules: link and validate the applications this one depends on — a no-op for services without rules.\n        applicationRelationService.linkForSubmission(application, relationApplicationId != null ? List.of(relationApplicationId) : List.of());\n\n        if (application.isPaymentSettled()) {\n            return finalizeSubmission(application, strategy);\n        }\n\n        boolean paymentRequired = application.isAwaitingPayment() || forcePaymentFirst || reviewService.isPaymentStep(applicationId);\n\n        if (paymentRequired) {\n            List<ApplicationRequestServiceDto> items = strategy.getApplicationRequestServices(application);\n\n            application.setStatus(ApplicationStatus.AWAITING_PAYMENT);\n            application.setPaymentStatus(ApplicationPaymentStatus.PENDING);\n            application.setPaymentContext(PaymentContext.SUBMISSION);\n            application = applicationRepository.saveAndFlush(application);\n\n            InvoiceResponseDto invoice = invoiceService.issueInvoice(application, items);\n\n            if (invoice.isFreeOrWaived()) {\n                return SubmitApplicationResult.submitted(application);\n            }\n\n            return SubmitApplicationResult.awaitingPayment(application, invoice);\n        }\n\n        return finalizeSubmission(application, strategy);\n    }"
  },
  "rCommonfinalizeSubmission": {
    "repo": "MOH-Application",
    "rev": "8f1db657315e",
    "path": "src/main/java/kh/gov/esb/application/modules/application/service/ApplicationServiceImpl.java",
    "line": 421,
    "code": "    private SubmitApplicationResult finalizeSubmission(Application application, ApplicationStrategy strategy) {\n        Instant now = Instant.now();\n        ApplicationStatus submittedStatus = application.getStatus() == ApplicationStatus.RETURNED ? ApplicationStatus.RE_SUBMITTED : ApplicationStatus.SUBMITTED;\n        application.setSubmittedDate(now);\n        if (application.getFirstSubmittedDate() == null) {\n            application.setFirstSubmittedDate(now);\n        }\n\n        // Every path into review (direct submit and paid-after-submit) passes here, so this is the one relation gate.\n        switch (applicationRelationService.evaluate(application)) {\n            case WAITING -> {\n                // Held: no ApplicationSubmittedDomainEvent, so the review service never sees it until released.\n                application.setStatus(ApplicationStatus.WAITING_RELATION);\n                application = applicationRepository.save(application);\n                applicationEventPublisher.publishEvent(new ApplicationStatusUpdatedDomainEvent(application));\n                return SubmitApplicationResult.submitted(application);\n            }\n            case RELATED_REJECTED -> {\n                application = applicationRepository.save(application);\n                returnForRejectedRelation(application);\n                return SubmitApplicationResult.submitted(application);\n            }\n            default -> {\n                // OPEN: fall through to review.\n            }\n        }\n\n        application.setStatus(submittedStatus);\n        application = applicationRepository.save(application);\n        strategy.sendNotifications(application, ApplicationStrategyAction.SUBMIT);\n        return SubmitApplicationResult.submitted(application);\n    }"
  },
